// Java emitter (clients/java, package io.github.xantiagoma.xtandard.image):
// writes src/generated/java/io/github/xantiagoma/xtandard/image/ from the
// spec. That directory is a second source root (build-helper-maven-plugin),
// so the generated files sit in the library's package but outside
// src/main/java, which Spotless formats.
//
//   ProcessingMethods, InfoMethods, VideoMethods
//                    generic interfaces with one default method per option
//                    name and alias and argument shape (the typed option
//                    values); ProcessingOptions and the fluent chains
//                    implement them
//   OptionTables     name or alias to canonical name, canonical to short
//   QueryParams, ImaginaryParams
//                    native query keys and imaginary parameters, one typed
//                    method per key and alias
//   ImageFormat, VideoContainer, StreamProtocol, SegmentFormat,
//   SourceEncoding, SourceScheme, ImaginaryEndpoint
//                    enums of the spec's value lists
//   Constants        signing, encryption, URL and stream constants, error
//                    kinds and their statuses
//   InfoResponse, ErrorResponse and the records they reference
//                    the JSON bodies, decoded by the internal JSON parser
//
// Java 17: records, no pattern-matching switch. Nullability is JSpecify
// (@NullMarked package, @Nullable where null is allowed).
//
// This file is the refiner (WP-146): it lowers the neutral model (build.ts)
// into Java nodes (model.ts), which lang/java.ts prints.

import {
  catalogues,
  type CatalogueModel,
  defaultSegmentFormat,
  imaginaryParams,
  nativeVideoKeys,
  type OptionModel,
  refName,
  responseSchemas,
  schemaTypes,
  type SchemaModel,
} from "../build.ts";
import { camel, constant, J, JavaPrinter, jd } from "../lang/java.ts";
import type { Shape } from "../lib.ts";
import { type Expr, N, type Node, type Param, type Stmt, type TypeRef } from "../model.ts";
import type { CatalogueKind, Emitter, JSONSchema, Spec, SpecArg } from "../spec.ts";

const dir = "clients/java/src/generated/java/io/github/xantiagoma/xtandard/image/";
const pkg = "io.github.xantiagoma.xtandard.image";
const printer = new JavaPrinter();

/** Builder methods the per-option methods must not shadow (and java.lang.Object's). */
export const reservedMethods = new Set([
  "option",
  "options",
  "pipeline",
  "extension",
  "encoding",
  "withPdfPassword",
  "build",
  "param",
  "params",
  "entries",
  "isEmpty",
  "self",
  "create",
  "toString",
  "equals",
  "hashCode",
  "getClass",
  "notify",
  "notifyAll",
  "wait",
  "clone",
  "finalize",
]);

// ---- nodes ---------------------------------------------------------------------------

const t = (name: string, ...args: TypeRef[]) => N.tref(name, args);
const id = N.id;
const String_ = t("String");
const nullableT = J.nullable;
const doc = (...ls: string[]) => N.comment("doc", ls.flatMap((l) => l.split("\n")));
/** A dotted name as member accesses (java.util.List). */
function qualified(name: string): Expr {
  const [head = "", ...rest] = name.split(".");
  return rest.reduce<Expr>((obj, part) => N.get(obj, part), id(head));
}
const listOf = (values: readonly (string | number)[], list: Expr = id("List")) => N.invoke(list, "of", values.map(N.scalar));
const mapEntry = (k: string, v: Expr) => N.invoke(id("Map"), "entry", [N.str(k), v]);
const mapOf = (entries: readonly (readonly [string, Expr])[]) =>
  N.invoke(id("Map"), "ofEntries", entries.map(([k, v]) => mapEntry(k, v)), { layout: "expanded" });

/** The header comment, the package and the imports of a file, then its declaration. */
function file(what: string, imports: readonly string[], decl: Node): Node {
  return N.file([
    N.comment("line", ["Code generated by clients/codegen/emitters/java.ts from clients/spec/spec.json. DO NOT EDIT.", `Run \`task clients:generate\`. ${what}`]),
    N.blank(),
    J.package(pkg),
    N.blank(),
    ...(imports.length ? [...imports.map((i) => N.imp(i)), N.blank()] : []),
    decl,
  ]);
}

// ---- option methods ---------------------------------------------------------

interface JParam {
  /** Java type in the signature. */
  type: TypeRef;
  /** Erasure, for duplicate detection. */
  erasure: string;
  name: string;
  doc: string;
  variadic: boolean;
}

/** Java type of one argument in a method signature. */
function argType(a: SpecArg): { type: TypeRef; erasure: string } {
  const boxed = (box: string, prim: string) => (a.nullable ? { type: nullableT(t(box)), erasure: box } : { type: t(prim), erasure: prim });
  switch (a.type) {
    case "integer":
      return boxed("Number", "long");
    case "number":
      return boxed("Number", "double");
    case "boolean":
      return boxed("Boolean", "boolean");
    case "direction":
      return boxed("Object", "Object");
    default:
      return boxed("String", "String");
  }
}

function argDoc(a: SpecArg): string {
  const parts: string[] = [];
  if (a.doc) parts.push(a.doc);
  if (a.type === "enum" && a.enum) parts.push(`one of ${a.enum.map((v) => `"${v}"`).join(", ")}`);
  if (a.type === "direction") parts.push(`"down", "up", "left", "right" or a number`);
  if (a.type === "color") parts.push("a hex colour");
  if (a.type === "base64") parts.push("URL-safe base64");
  if (a.min !== undefined && a.max !== undefined) parts.push(`${a.min} to ${a.max}`);
  else if (a.min !== undefined) parts.push(`at least ${a.min}`);
  else if (a.max !== undefined) parts.push(`at most ${a.max}`);
  if (a.nullable) parts.push("null writes an empty argument");
  return parts.join("; ") || a.name;
}

/** The varargs element type of a rest group (one type, else nullable Object). */
function restType(rest: readonly SpecArg[]): { type: TypeRef; erasure: string } {
  const types = new Set(rest.map((a) => JSON.stringify(argType(a).type)));
  if (types.size === 1) {
    const x = argType(rest[0]!);
    return { type: x.type, erasure: `${x.erasure}[]` };
  }
  return { type: nullableT(t("Object")), erasure: "Object[]" };
}

function shapeParams(s: Shape): { params: JParam[]; rest?: JParam } {
  const used = new Map<string, number>();
  const name = (n: string) => {
    let x = camel(n);
    const c = used.get(x) ?? 0;
    used.set(x, c + 1);
    if (c > 0) x = `${x}${c + 1}`;
    return x;
  };
  const params = s.fixed.map((a) => ({ ...argType(a), name: name(a.name), doc: argDoc(a), variadic: false }));
  if (!s.rest) return { params };
  const restDoc = `repeated ${s.rest.map((a) => a.name).join(", ")}: ${s.rest.map(argDoc).join(" / ")}`;
  return { params, rest: { ...restType(s.rest), name: name(s.rest.length === 1 ? `${s.rest[0]!.name}s` : "rest"), doc: restDoc, variadic: true } };
}

function optionDoc(o: OptionModel): string[] {
  return [jd(o.spec.doc), "", `<p>${jd(`URL names: ${o.names.join(", ")}; arguments ${o.spec.syntax}; default ${o.spec.default}.`)}`, jd(`${o.tags.join("; ")}.`)];
}

const kindPrefix: Record<CatalogueKind, string> = { processing: "Processing", info: "Info", video: "Video" };
const self = t("S");

function emitMethods(c: CatalogueModel): Node {
  const { kind } = c;
  const K = kindPrefix[kind];
  const members: Node[] = [
    N.blank(),
    N.func("option", [N.param("name", String_), N.param("args", nullableT(t("Object")), { mods: ["variadic"] })], undefined, {
      returns: self,
      doc: doc(
        "Appends one option occurrence (what the per-option methods call).",
        "",
        "@param name an option name or alias",
        "@param args the arguments: strings, numbers, booleans or null (an empty argument)",
        "@return this",
      ),
    }),
  ];
  const used = new Map<string, string>();
  for (const o of c.options) {
    const allShapes = o.shapes.map(shapeParams);
    for (const n of o.names) {
      const name = camel(n);
      if (reservedMethods.has(name)) throw new Error(`${kind} option ${n} collides with the builder method ${name}`);
      const prev = used.get(name);
      if (prev !== undefined) throw new Error(`${kind} option names ${prev} and ${n} are both the Java method ${name}`);
      used.set(name, n);
      const seen = new Set<string>();
      for (const sh of allShapes) {
        const ps = [...sh.params, ...(sh.rest ? [sh.rest] : [])];
        const erasure = JSON.stringify(ps.map((p) => p.erasure));
        if (seen.has(erasure)) continue;
        seen.add(erasure);
        const fixed = sh.params.map((p) => id(p.name));
        const args: Expr[] = sh.rest
          ? [N.invoke(id("Args"), "concat", [J.newArray(nullableT(t("Object")), fixed), id(sh.rest.name)])]
          : fixed;
        members.push(
          N.blank(),
          N.func(
            name,
            ps.map((p): Param => N.param(p.name, p.type, p.variadic ? { mods: ["variadic"] } : {})),
            [N.ret(N.call(id("option"), [N.str(n), ...args]))],
            { returns: self, mods: ["default"], doc: doc(...optionDoc(o), "", ...ps.map((p) => `@param ${p.name} ${jd(p.doc)}`), "@return this") },
          ),
        );
      }
      if (allShapes.length === 0) throw new Error(`${kind} option ${o.name} has no argument shapes`);
    }
  }
  const iface = N.type("interface", `${K}Methods`, members, {
    mods: ["public"],
    typeParams: [J.typeParam("S", t(`${K}Methods`, self))],
    doc: doc(
      `One method per ${kind} option name and alias, with one overload per argument shape; each appends`,
      "that option, written with the name as called (option names {@code GIVEN}), its short name (default)",
      "or its canonical name.",
      "",
      "<p>Numbers are written as ECMAScript writes them ({@code 300}, {@code 1.5}), booleans as {@code 1}",
      "and {@code 0}, and a null argument is an empty one.",
      "",
      "@param <S> the implementing type, returned by every method",
    ),
  });
  return file(`The typed ${kind} option methods.`, ["org.jspecify.annotations.Nullable"], iface);
}

const stringMap = t("Map", String_, String_);

function emitTables(cats: readonly CatalogueModel[]): Node {
  const members: Node[] = [N.func("OptionTables", [], [], { mods: ["private"] })];
  for (const c of cats) {
    const K = c.kind.toUpperCase();
    members.push(
      N.blank(),
      N.const(`${K}_NAMES`, mapOf(c.names.map(([n, canonical]) => [n, N.str(canonical)])), {
        type: stringMap,
        mods: ["static", "final"],
        doc: doc(`${c.kind} option name or alias to canonical name.`),
      }),
      N.blank(),
      N.const(`${K}_SHORT`, mapOf(c.options.map((o) => [o.name, N.str(o.short)])), {
        type: stringMap,
        mods: ["static", "final"],
        doc: doc(`Canonical ${c.kind} option name to the name builders write by default (the shortest).`),
      }),
    );
  }
  const cls = N.type("class", "OptionTables", members, {
    mods: ["final"],
    doc: doc("Option name tables: every name and alias to its canonical name, and canonical to short names."),
  });
  return file("Option name tables of the processing, /info and /video catalogues.", ["java.util.Map"], cls);
}

// ---- enums and constants ----------------------------------------------------

const ret = (e: Expr): Stmt[] => [N.ret(e)];

function emitEnum(name: string, what: string, values: { value: string; doc?: string }[], extra: Node[] = []): Node {
  const value = id("value");
  const body: Node[] = [
    N.blank(),
    N.field("value", String_, { mods: ["private", "final"] }),
    N.blank(),
    N.func(name, [N.param("value", String_)], [N.stmt(N.binary("=", N.get(id("this"), "value"), value))]),
    N.blank(),
    N.func("value", [], ret(value), { returns: String_, mods: ["public"], doc: doc("The value as written in URLs.", "", "@return the value") }),
    N.blank(),
    N.func("toString", [], ret(value), { returns: String_, mods: ["public"], annotations: [N.annotation("Override")] }),
    ...extra,
  ];
  const members = values.map((v) => N.member(constant(v.value), undefined, { args: [N.str(v.value)], doc: doc(v.doc ? jd(v.doc) : `{@code ${jd(v.value)}}.`) }));
  return file(what, [], N.enum(name, members, { body, mods: ["public"], doc: doc(jd(what)) }));
}

const constDecl = (what: string, type: TypeRef, name: string, value: Expr): Node[] => [
  N.blank(),
  N.const(name, value, { type, mods: ["public", "static", "final"], doc: doc(jd(what)) }),
];

function emitConstants(spec: Spec): Node {
  const s = spec.media.streams;
  const sg = spec.signing;
  const en = spec.encryption;
  const u = spec.url;
  const int = t("int");
  const strings = t("List", String_);
  const members: Node[] = [
    N.func("Constants", [], [], { mods: ["private"] }),
    ...constDecl("Version of the spec these classes were generated from.", int, "SPEC_VERSION", N.int(spec.spec_version)),
    ...constDecl("Smallest signature size in bytes.", int, "MIN_SIGNATURE_SIZE", N.int(sg.min_size)),
    ...constDecl("Largest signature size in bytes.", int, "MAX_SIGNATURE_SIZE", N.int(sg.max_size)),
    ...constDecl("Default signature size in bytes (XI_SIGNING_SIZE).", int, "DEFAULT_SIGNATURE_SIZE", N.int(sg.default_size)),
    ...constDecl("Signature segments of unsigned URLs.", strings, "UNSIGNED_PLACEHOLDERS", listOf(sg.unsigned_placeholders)),
    ...constDecl("Default signature segment of unsigned URLs.", String_, "DEFAULT_UNSIGNED", N.str(sg.default_unsigned)),
    ...constDecl("Query parameter of the xi_sig signature.", String_, "XI_SIG_PARAM", N.str(sg.query_param)),
    ...constDecl("AES key sizes in bytes.", t("List", t("Integer")), "ENCRYPTION_KEY_SIZES", listOf(en.key_sizes)),
    ...constDecl("AES-CBC IV size in bytes.", int, "IV_SIZE", N.int(en.iv_size)),
    ...constDecl("Prefix of encrypted sources.", String_, "ENCRYPTED_SOURCE_PREFIX", N.str(en.source_prefix)),
    ...constDecl("Longest PDF password in UTF-8 bytes.", int, "MAX_PDF_PASSWORD_BYTES", N.int(en.max_pdf_password_bytes)),
    ...constDecl("Canonical name of the PDF password option.", String_, "PDF_PASSWORD_NAME", N.str(en.pdf_password_names[0]!)),
    ...constDecl("Short name of the PDF password option.", String_, "PDF_PASSWORD_SHORT", N.str(en.pdf_password_short_name)),
    ...constDecl("Default argument separator.", String_, "DEFAULT_SEPARATOR", N.str(u.default_separator)),
    ...constDecl("Separators the imgproxy grammar forbids.", strings, "FORBIDDEN_SEPARATORS", listOf(u.forbidden_separators)),
    ...constDecl("Separators the query dialect forbids inside o=.", strings, "FORBIDDEN_QUERY_SEPARATORS", listOf(u.forbidden_query_separators)),
    ...constDecl("Segment between chained pipelines.", String_, "PIPELINE_SEPARATOR", N.str(u.pipeline_separator)),
    ...constDecl("Characters a plain source keeps verbatim besides ASCII letters and digits.", String_, "PLAIN_SAFE", N.str(u.plain_safe)),
    ...constDecl("Characters a query key or value keeps verbatim besides ASCII letters and digits.", String_, "QUERY_SAFE", N.str(u.query_safe)),
    ...constDecl("Pattern an extension must match.", String_, "EXTENSION_PATTERN", N.str(u.extension_pattern)),
    ...constDecl("Pattern of xi:// source names.", String_, "XI_NAME_PATTERN", N.str(spec.sources.xi_name_pattern)),
    ...constDecl("Default mount of the query dialect (XI_DIALECTS_QUERY_PREFIX).", String_, "QUERY_MOUNT", N.str(spec.query.mount)),
    ...constDecl("/q/video keys written differently from the /video option name.", stringMap, "NATIVE_VIDEO_KEYS", mapOf(nativeVideoKeys(spec).map(([k, v]) => [k, N.str(v)]))),
    ...constDecl("Most renditions of one stream.", int, "MAX_RENDITIONS", N.int(s.max_renditions)),
    ...constDecl("Smallest rendition (short side of the frame).", int, "RENDITION_MIN", N.int(s.rendition_min)),
    ...constDecl("Largest rendition (short side of the frame).", int, "RENDITION_MAX", N.int(s.rendition_max)),
    ...constDecl("Shortest segment duration in seconds.", int, "SEGMENT_DURATION_MIN", N.int(s.segment_duration_min)),
    ...constDecl("Longest segment duration in seconds.", int, "SEGMENT_DURATION_MAX", N.int(s.segment_duration_max)),
    ...constDecl(
      "Error kinds of the server's JSON error envelope, with their HTTP status.",
      t("Map", String_, t("Integer")),
      "ERROR_STATUS",
      mapOf(spec.error_kinds.map((e) => [e.kind, N.int(e.status)])),
    ),
  ];
  const cls = N.type("class", "Constants", members, {
    mods: ["public", "final"],
    doc: doc("Constants of the client specification (clients/spec/spec.json): signing, encryption, URLs, streams."),
  });
  return file("Constants of the client specification.", ["java.util.List", "java.util.Map"], cls);
}

/** A method returning a switch expression over the enum's constants. */
function switchMethod(name: string, returns: TypeRef, lines: string[], arms: [string, Expr][]): Node[] {
  return [
    N.blank(),
    N.func(name, [], ret(J.switchExpr(id("this"), arms.map(([m, v]) => ({ match: id(m), value: v })))), {
      returns,
      mods: ["public"],
      doc: doc(...lines),
    }),
  ];
}

function emitEnums(spec: Spec): Record<string, Node> {
  const s = spec.media.streams;
  const files: Record<string, Node> = {};
  files["ImageFormat"] = emitEnum("ImageFormat", "Output formats of the processing format option.", spec.media.image_formats.map((value) => ({ value })));
  files["VideoContainer"] = emitEnum("VideoContainer", "Output containers of /video URLs.", spec.media.video_containers.map((value) => ({ value })));
  files["StreamProtocol"] = emitEnum(
    "StreamProtocol",
    "Adaptive streaming protocols: HLS or DASH.",
    s.protocols.map((p) => ({ value: p.name, doc: `${p.name}: a ${p.container} manifest (${p.content_type}).` })),
    [
      ...switchMethod(
        "container",
        String_,
        ["The manifest container, the extension of a stream URL.", "", "@return {@code m3u8} or {@code mpd}"],
        s.protocols.map((p) => [constant(p.name), N.str(p.container)]),
      ),
      ...switchMethod(
        "contentType",
        String_,
        ["The manifest media type.", "", "@return the Content-Type of the manifest"],
        s.protocols.map((p) => [constant(p.name), N.str(p.content_type)]),
      ),
    ],
  );
  files["SegmentFormat"] = emitEnum(
    "SegmentFormat",
    "Stream segment containers.",
    s.segment_formats.map((f) => ({
      value: f.name,
      doc: `${f.name} (aliases ${f.aliases.join(", ")}): ${f.protocols.join(" and ")}${f.default ? "; the default" : ""}.`,
    })),
    [
      N.blank(),
      N.const("DEFAULT", id(constant(defaultSegmentFormat(spec))), {
        type: t("SegmentFormat"),
        mods: ["public", "static", "final"],
        doc: doc("The default segment format, which stream URLs leave out."),
      }),
      ...switchMethod(
        "protocols",
        t("java.util.List", String_),
        ["The protocols that accept this segment format.", "", "@return protocol names"],
        s.segment_formats.map((f) => [constant(f.name), listOf(f.protocols, qualified("java.util.List"))]),
      ),
    ],
  );
  files["SourceEncoding"] = emitEnum("SourceEncoding", "How a source is written in an imgproxy URL.", spec.sources.encodings.map((value) => ({ value })));
  files["SourceScheme"] = emitEnum(
    "SourceScheme",
    "Source schemes the server resolves.",
    spec.sources.schemes.map((x) => ({ value: x.scheme, doc: `${x.scheme}: authority ${x.authority}, e.g. ${x.example}.` })),
  );
  files["ImaginaryEndpoint"] = emitEnum("ImaginaryEndpoint", "imaginary endpoints of /q/<endpoint>.", spec.query.imaginary.endpoints.map((value) => ({ value })));
  return files;
}

// ---- query parameters -------------------------------------------------------

function emitParams(name: string, what: string, keys: readonly { name: string; aliases: readonly string[]; doc: string }[]): Node {
  const self_ = t(name);
  const members: Node[] = [
    N.blank(),
    N.func(name, [], [], { mods: ["private"] }),
    N.blank(),
    N.func("create", [], ret(N.new(self_)), { returns: self_, mods: ["public", "static"], doc: doc("Starts an empty parameter list.", "", "@return a new list") }),
    N.blank(),
    N.func("self", [], ret(id("this")), { returns: self_, annotations: [N.annotation("Override")] }),
  ];
  const used = new Set<string>();
  for (const k of keys) {
    for (const n of [k.name, ...k.aliases]) {
      const method = camel(n);
      if (reservedMethods.has(method)) throw new Error(`${name} key ${n} collides with the method ${method}`);
      if (used.has(method)) throw new Error(`${name} keys collide on ${method}`);
      used.add(method);
      for (const [type, desc] of [
        ["String", "the value"],
        ["long", "the value"],
        ["double", "the value"],
        ["boolean", "the value, written true or false"],
      ] as const) {
        members.push(
          N.blank(),
          N.func(method, [N.param("value", t(type))], ret(N.call(id("param"), [N.str(n), id("value")])), {
            returns: self_,
            mods: ["public"],
            doc: doc(
              jd(k.doc || `The ${k.name} parameter.`),
              "",
              jd(`Key ${n}${k.aliases.length ? ` (names: ${[k.name, ...k.aliases].join(", ")})` : ""}.`),
              "",
              `@param value ${desc}`,
              "@return this",
            ),
          }),
        );
      }
    }
  }
  const cls = N.type("class", name, members, {
    mods: ["public", "final"],
    supers: [t("ParamList", self_)],
    doc: doc(
      jd(what),
      "",
      "<p>Keys are written in the order they are added, after {@code url}; booleans are {@code true} or",
      "{@code false} and numbers are written as ECMAScript writes them. {@link #param} adds any key.",
    ),
  });
  return file(what, [], cls);
}

// ---- response records -------------------------------------------------------

/** How a JSON value decodes into a Java type. */
interface JType {
  /** Declared type of a nullable component. */
  boxed: TypeRef;
  /** Declared type of a required component (primitive where possible). */
  required: TypeRef;
  /** Whether the type is a List or contains a Map (the imports it needs). */
  list: boolean;
  map: boolean;
  /** Expression decoding JSON value v (an Object) at where; d numbers nested lambda parameters. */
  decode: (v: Expr, where: Expr, d: number) => Expr;
}

const jv = (fn: string, ...args: Expr[]) => N.invoke(id("JsonValues"), fn, args);
const nonNull = (x: string, w: string) => jv("nonNull", id(x), id(w));
const lambda = (x: string, w: string, body: Expr) => N.lambda([N.param(x), N.param(w)], body);

function simple(boxed: string, required: string, fn: string): JType {
  return { boxed: t(boxed), required: t(required), list: false, map: false, decode: (v, w) => jv(fn, v, w) };
}

function schemaJType(s: JSONSchema): JType {
  if (s.$ref) {
    const n = refName(s.$ref);
    return { boxed: t(n), required: t(n), list: false, map: false, decode: (v, w) => N.invoke(id(n), "fromJsonValue", [v, w]) };
  }
  const types = schemaTypes(s).filter((x) => x !== "null");
  switch (types.length === 1 ? types[0] : undefined) {
    case "string":
      return simple("String", "String", "string");
    case "integer":
      return simple("Long", "long", "integer");
    case "number":
      return simple("Double", "double", "number");
    case "boolean":
      return simple("Boolean", "boolean", "bool");
    case "array": {
      const e = s.items ? schemaJType(s.items) : undefined;
      if (!e) {
        const raw = t("List", nullableT(t("Object")));
        return { boxed: raw, required: raw, list: true, map: false, decode: (v, w) => jv("rawList", v, w) };
      }
      const x = t("List", e.boxed);
      return {
        boxed: x,
        required: x,
        list: true,
        map: e.map,
        decode: (v, w, d) => jv("list", v, w, lambda(`x${d}`, `w${d}`, e.decode(nonNull(`x${d}`, `w${d}`), id(`w${d}`), d + 1))),
      };
    }
    case "object": {
      if (s.properties) throw new Error("inline object schemas are not supported");
      const ap = s.additionalProperties;
      if (typeof ap === "object" && (ap.type !== undefined || ap.$ref !== undefined)) {
        const e = schemaJType(ap);
        const x = t("Map", String_, e.boxed);
        return {
          boxed: x,
          required: x,
          list: false,
          map: true,
          decode: (v, w, d) => jv("map", v, w, lambda(`x${d}`, `w${d}`, e.decode(nonNull(`x${d}`, `w${d}`), id(`w${d}`), d + 1))),
        };
      }
      const raw = t("Map", String_, nullableT(t("Object")));
      return { boxed: raw, required: raw, list: false, map: true, decode: (v, w) => jv("rawMap", v, w) };
    }
    default:
      return { boxed: t("Object"), required: t("Object"), list: false, map: false, decode: (v) => v };
  }
}

function emitRecord(sm: SchemaModel): Node {
  const { name, schema: s } = sm;
  // Properties in the schema's order (the record's component order).
  const comps = Object.entries(s.properties ?? {}).map(([p, ps]) => {
    const required = sm.required.has(p);
    const nullableType = (Array.isArray(ps.type) && ps.type.includes("null")) || !required;
    return { json: p, id: camel(p), t: schemaJType(ps), required: required && !nullableType, doc: ps.description };
  });
  const where = id("where");
  const args = comps.map((c) => {
    const w = N.binary("+", where, N.str(`.${c.json}`));
    if (c.required) return c.t.decode(jv("required", id("o"), N.str(c.json), where), w, 0);
    return jv("optional", N.invoke(id("o"), "get", [N.str(c.json)]), w, lambda("x", "xw", c.t.decode(nonNull("x", "xw"), id("xw"), 0)));
  });
  const [first = "", ...more] = jd(s.description ?? `The ${name} object.`).split("\n");
  const members: Node[] = [
    N.blank(),
    N.func("fromJson", [N.param("json", String_)], ret(N.call(id("fromJsonValue"), [N.invoke(id("Json"), "parse", [id("json")]), N.str(name)])), {
      returns: t(name),
      mods: ["public", "static"],
      doc: doc(
        `Decodes {@code ${name}} JSON text.`,
        "",
        "@param json the JSON document",
        "@return the decoded value",
        "@throws IllegalArgumentException the text is not JSON or does not have this shape",
      ),
    }),
    N.blank(),
    N.func(
      "fromJsonValue",
      [N.param("value", nullableT(t("Object"))), N.param("where", String_)],
      [
        N.let("o", jv("object", id("value"), where), { type: t("Map", String_, nullableT(t("Object"))) }),
        N.ret(N.new(t(name), args, { layout: "expanded" })),
      ],
      { returns: t(name), mods: ["static"] },
    ),
  ];
  const record = N.type("record", name, members, {
    mods: ["public"],
    params: comps.map((c) => N.param(c.id, c.required ? c.t.required : nullableT(c.t.boxed))),
    doc: doc(
      first,
      ...more.map((l) => `<br>${l}`),
      "",
      ...comps.map((c) => `@param ${c.id} {@code ${jd(c.json)}}${c.doc ? `: ${jd(c.doc)}` : ""}${c.required ? "" : " (null when absent)"}`),
    ),
  });
  // fromJsonValue always reads a Map.
  const imports = [...(comps.some((c) => c.t.list) ? ["java.util.List"] : []), "java.util.Map", "org.jspecify.annotations.Nullable"];
  return file(`The ${name} JSON body.`, imports, record);
}

export const emitter: Emitter = {
  language: "java",
  emit(spec) {
    const cats = catalogues(spec);
    const files: Record<string, Node> = {};
    for (const c of cats) files[`${kindPrefix[c.kind]}Methods`] = emitMethods(c);
    files["OptionTables"] = emitTables(cats);
    files["Constants"] = emitConstants(spec);
    Object.assign(files, emitEnums(spec));
    files["QueryParams"] = emitParams("QueryParams", "Native keys of the query dialect's image endpoint (/q/?url=…&w=300&f=webp).", spec.query.image_keys);
    files["ImaginaryParams"] = emitParams(
      "ImaginaryParams",
      "Parameters of the query dialect's imaginary endpoints (/q/resize?url=…&width=300).",
      imaginaryParams(spec).map((p) => ({ name: p, aliases: [], doc: "" })),
    );
    for (const sm of responseSchemas(spec)) files[sm.name] = emitRecord(sm);
    return Object.fromEntries(Object.entries(files).map(([n, f]) => [`${dir}${n}.java`, printer.print(f)]));
  },
};
